  @property({type: Boolean}) showGpsSatellites: boolean = false;
  @property({type: Boolean}) showGlonassSatellites: boolean = false;
  @property({type: Boolean}) showGalileioSatellites: boolean = false;
  @property({type: Boolean}) showBeiDouSatellites: boolean = false;

  @property({type: Boolean}) showSatelliteIDs: boolean = false;
  @property({type: Boolean}) showStrongSignalsOnly: boolean = false;
  @property({type: Boolean}) showActiveSatellitesOnly: boolean = false;

  override render() {
    // this.satellites = this.mapSatellitesToCircle(this.generateRandomSatellites());
    this.satellites = this.mapSatellitesToCircle(this.satellites);
    return html`
      <div class="container">
        ${this.getGnssSkylot()}
      </div>
    `;
  }
  
  static override styles = [
    skyplotStyles
  ];

  private mapSatellitesToCircle(
    input: SatelliteData[]
  ): (SatelliteData & { x: number; y: number })[] {

    const centerX = -58;
    const centerY = 168;

    const maxRadius = 227.84; // outer ring

    return input.map(s => {

      const angle = (s.azimuth * Math.PI) / 180;

      const clamped = Math.max(0, Math.min(90, s.elevation));
    
      const radius = maxRadius * Math.cos((clamped * Math.PI) / 180);

      const x = Math.round(centerX + Math.sin(angle) * radius);
      const y = Math.round(centerY - Math.cos(angle) * radius);

      s.strength = this.mapStrength(s.strength);

      return {
        ...s,
        x,
        y
      };
    });
  }

  // TODO check the right satellite strength
  private mapStrength(value: number): Strength {
    if (value <= 0) return Strength.None;
    if (value < 30) return Strength.Weak;
    if (value < 70) return Strength.Medium;
    return Strength.Strong;
  }

  private handleClickOnSatellite(id: number) {
    const clickedSatellite = this.satellites.find(s => s.id === id);

    if (!clickedSatellite) return;

    window.dispatchEvent(
      new CustomEvent<Satellite>('satellite', {
        detail: clickedSatellite
      })
    );

    // TODO: remove
    console.log(clickedSatellite);
  }

  getGnssSkylot() {
    return svg`
      <svg width="512" height="512" viewBox="16 132 600 572" fill="none" xmlns="http://www.w3.org/2000/svg">

        <g clip-path="url(#clip0_2673_56153)">
          ${this.getLabels()}
          ${this.getOuterRing()}
          ${this.getTickmarks()}
          ${this.getRings()}
          ${this.getRingsAngle()}
        </g>

        ${this.getSatellites()}
        
      </svg>
    `;
  }

