  private getText(id: number, strength: number) {
    return svg`
      <text
        x="378"
        y="242"
        text-anchor="middle"
        dominant-baseline="central"
        font-size="20"
        font-weight="bold"
        fill="${this.getTextFillColor(strength)}"
        stroke="${Colors.elementActiveInvertedColor}"
        stroke-width="0.5"
        paint-order="stroke">
        ${id}
      </text>
    `;
  }

  private getTextFillColor(strength: number) {
    if (strength == Strength.Strong) {
      return Colors.elementActiveInvertedColor;
    }
    else if (strength == Strength.Medium) {
      return Colors.elementActiveColor;
    }
    else if (strength == Strength.Weak) {
      return Colors.elementNeutralColor;
    }
    else { // strength == Strength.None
      return Colors.elementDisabledColor;
    }
  }

